shell_commands.command:
cd /testbed && find tests/tmp -name '*.log' -o -name '*stdout*' | head -25; grep -nE -A18 -B4 'BUG REPORT|signal|ACLLoadFromFile|acl.c:|crashed' tests/tmp/server.*/stdout | tail -115; git --no-pager diff --stat && git apply --recount <<'PATCH'
diff --git a/src/acl.c b/src/acl.c
--- a/src/acl.c
+++ b/src/acl.c
@@ -2379,6 +2379,8 @@
         listRewind(server.clients, &li);
         while ((ln = listNext(&li)) != NULL) {
             client *c = listNodeValue(ln);
+            /* Clients without an ACL user, such as the primary, are not affected by ACL changes. */
+            if (c->user == NULL) continue;
             user *original = c->user;
             list *channels = NULL;
             user *new_user = ACLGetUserByName(c->user->name, sdslen(c->user->name));
PATCH
make -j4 > /tmp/valkey-acl-load-build.log 2>&1 && tail -8 /tmp/valkey-acl-load-build.log

